#!/bin/sh

# Local build and runtime smoke test for the Galène image.
#
# Builds the image for the native architecture, checks the image layout,
# starts the server with an isolated throwaway configuration, fetches the
# web UI through the container's HTTP listener, runs galenectl, and verifies
# graceful shutdown on SIGTERM.
#
# Usage: sh ci/smoke-test.sh
#
# Requires GALENE_TAG (plus GALENE_VERSION/GALENE_COMMIT/GALENE_CREATED/
# SOURCE_DATE_EPOCH if known); missing values are read from
# .woodpecker/release.env as generated by ci/prepare-release.sh.
#
# On hosts whose Docker CLI lacks the buildx plugin, run this through the
# docker:28-cli image (which bundles buildx and talks to the host daemon):
#
#   docker run --rm \
#     -v /var/run/docker.sock:/var/run/docker.sock \
#     -v "$PWD:$PWD" -w "$PWD" \
#     docker:28-cli sh ci/smoke-test.sh

set -eu

cd "$(dirname "$0")/.."

if [ -z "${GALENE_TAG:-}" ] && [ -f .woodpecker/release.env ]; then
	# shellcheck disable=SC1091
	. .woodpecker/release.env
fi

: "${GALENE_TAG:?GALENE_TAG is required (export it or generate .woodpecker/release.env first)}"

GALENE_VERSION="${GALENE_VERSION:-${GALENE_TAG#galene-}}"
GALENE_COMMIT="${GALENE_COMMIT:-unknown}"
GALENE_CREATED="${GALENE_CREATED:-unknown}"
SOURCE_DATE_EPOCH="${SOURCE_DATE_EPOCH:-0}"

IMAGE_TAG="galene-docker-smoke"
container="galene-docker-smoke-$$-$(date +%s)"
http_url="http://127.0.0.1:8443/"

tmp_dir="$(mktemp -d)"
cleanup() {
	docker rm -f "${container}" > /dev/null 2>&1 || true
	rm -rf "${tmp_dir}"
}
trap cleanup EXIT INT TERM

fail() {
	echo "FAIL: $1" >&2
	exit 1
}

echo "Building image for the native architecture (GALENE_TAG=${GALENE_TAG})..."
docker build \
	--build-arg "GALENE_TAG=${GALENE_TAG}" \
	--build-arg "GALENE_VERSION=${GALENE_VERSION}" \
	--build-arg "GALENE_COMMIT=${GALENE_COMMIT}" \
	--build-arg "GALENE_CREATED=${GALENE_CREATED}" \
	--build-arg "SOURCE_DATE_EPOCH=${SOURCE_DATE_EPOCH}" \
	-t "${IMAGE_TAG}" .

echo "Checking image layout..."
docker run --rm --entrypoint sh "${IMAGE_TAG}" -c '
	set -eu
	test -x /usr/local/bin/galene
	test -x /usr/local/bin/galenectl
	test -f /app/static/galene.html
	test -f /usr/share/licenses/galene/LICENCE
	test -w /app/data && test -w /app/groups && test -w /app/recordings
	command -v go > /dev/null 2>&1 && {
		echo "Go toolchain leaked into the runtime image" >&2
		exit 1
	}
	[ "$(id -u)" = "1000" ] || {
		echo "runtime user is not uid 1000" >&2
		exit 1
	}
' || fail "image layout check failed"

echo "Starting the server with a throwaway configuration..."
docker run -d --name "${container}" "${IMAGE_TAG}" \
	-insecure -http 127.0.0.1:8443 -turn "" > /dev/null

echo "Waiting for the web UI to come up..."
ready=0
attempt=0
while [ "${attempt}" -lt 30 ]; do
	# The download is written to wget's stdout inside the server container
	# and redirected into a local file by this shell; a path under
	# "${tmp_dir}" would be interpreted inside the server container.
	if docker exec "${container}" wget -q -O - "${http_url}" > "${tmp_dir}/index.html" 2> /dev/null; then
		ready=1
		break
	fi
	if [ "$(docker inspect -f '{{.State.Running}}' "${container}")" != "true" ]; then
		echo "Server exited prematurely; container logs:" >&2
		docker logs "${container}" >&2 || true
		fail "server container exited before serving the web UI"
	fi
	attempt=$((attempt + 1))
	sleep 1
done

if [ "${ready}" != "1" ]; then
	echo "Server logs:" >&2
	docker logs "${container}" >&2 || true
	fail "web UI did not answer within 30 seconds"
fi

if ! grep -qi galene "${tmp_dir}/index.html"; then
	fail "served page does not mention Galène"
fi
echo "Web UI is served."

echo "Running galenectl via an entrypoint override..."
galenectl_rc=0
docker run --rm --entrypoint galenectl "${IMAGE_TAG}" -h \
	> "${tmp_dir}/galenectl.txt" 2>&1 || galenectl_rc=$?

case "${galenectl_rc}" in
	0)
		: ;;
	2)
		# Go's flag package may report usage with exit status 2.
		grep -qi "usage" "${tmp_dir}/galenectl.txt" \
			|| fail "galenectl exited 2 without usage output"
		;;
	*)
		echo "galenectl output:" >&2
		cat "${tmp_dir}/galenectl.txt" >&2 || true
		fail "galenectl -h exited with status ${galenectl_rc}"
		;;
esac
echo "galenectl executes."

echo "Stopping the container (SIGTERM)..."
stop_rc=0
docker stop -t 20 "${container}" > /dev/null || stop_rc=$?
[ "${stop_rc}" -eq 0 ] || fail "docker stop failed with status ${stop_rc}"

exit_code="$(docker inspect -f '{{.State.ExitCode}}' "${container}")"
if [ "${exit_code}" != "0" ]; then
	echo "Container logs:" >&2
	docker logs "${container}" >&2 || true
	fail "server did not shut down gracefully (exit code ${exit_code})"
fi
echo "Server shut down gracefully."

echo "All smoke tests passed."
